<?php if ($totalPages > 1): ?><nav class="pagination pagination-footer" aria-label="Páginas"><span>Página <?= $currentPage ?> de <?= $totalPages ?></span><?php foreach (array_unique(array_merge([1], range(max(1, $currentPage - 2), min($totalPages, $currentPage + 2)), [$totalPages])) as $number): ?><a class="<?= $number === $currentPage ? 'active' : '' ?>" href="index.php?<?= e(http_build_query(array_merge($paginationQuery, ['p' => $number]))) ?>" <?= $number === $currentPage ? 'aria-current="page"' : '' ?>><?= $number ?></a><?php endforeach ?></nav><?php endif ?>
